class Animal {
    public void vocalize() { System.out.println("Generic sound"); }
}

class Lion extends Animal {
    @Override public void vocalize() { System.out.println("Lion: Roar!"); }
}

class Wolf extends Animal {
    @Override public void vocalize() { System.out.println("Wolf: Howl!"); }
}

class Eagle extends Animal {
    @Override public void vocalize() { System.out.println("Eagle: Screech!"); }
}

public class Main {
    public static void main(String[] args) {
        Animal[] animals = new Animal[] { new Lion(), new Wolf(), new Eagle() };
        for (Animal a : animals) {
            a.vocalize();
        }
    }
}

