class GraphicElement {
    public void render() {
        System.out.println("Rendering generic element");
    }
}

class SvgElement extends GraphicElement {
    @Override
    public void render() {
        System.out.println("Rendering SVG: <polygon points=\"10,10 50,50\" />");
    }
}

class CanvasElement extends GraphicElement {
    @Override
    public void render() {
        System.out.println("Rendering Canvas: ctx.beginPath(); ctx.arc(100, 100, 50, 0, Math.PI*2);");
    }
}

class WebGlElement extends GraphicElement {
    @Override
    public void render() {
        System.out.println("Rendering WebGL: gl.drawArrays(gl.TRIANGLES, 0, 3);");
    }
}

public class Main {
    public static void drawScene(GraphicElement[] scene) {
        for (GraphicElement elem : scene) {
            elem.render();
        }
    }

    public static void main(String[] args) {
        GraphicElement[] scene = new GraphicElement[] {
            new SvgElement(),
            new CanvasElement(),
            new WebGlElement()
        };
        drawScene(scene);
    }
}
